#rf-root,.hf-root{--x3:#44545e;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;animation:st-fadein 0.5s ease-out both,st-zoomout 0.5s cubic-bezier(.7,0,.84,0) 4.5s both;}.cam{position:absolute;inset:0;animation:st-cam 5s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.wrap{position:absolute;left:90px;right:90px;top:0;bottom:0;display:flex;flex-direction:column;justify-content:center}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}.eb{display:inline-block;font:500 32px/1.2 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}@property --n83{syntax:'<integer>';inherits:false;initial-value:0}
.n83{counter-reset:n83 var(--n83);animation:n83-c 2s cubic-bezier(.16,1,.3,1) 0.75s both}
.n83::after{content:counter(n83,decimal)}
@keyframes n83-c{from{--n83:0}to{--n83:80}}.wrap{align-items:center;text-align:center}.wrap>div:first-child{margin-bottom:36px}
h2{margin:0 0 60px;font-size:82px;line-height:1;letter-spacing:-.035em;font-weight:var(--rf-heading-weight)}
.ring{position:relative;width:760px;height:760px}
.ring svg{transform:rotate(-90deg)}
.rt{fill:none;stroke:color-mix(in srgb,var(--rf-text) 10%,transparent);stroke-width:64}
.rv{fill:none;stroke:var(--rf-accent);stroke-width:64;stroke-linecap:round;stroke-dashoffset:80;animation:rv 2s cubic-bezier(.16,1,.3,1) 0.75s both}
@keyframes rv{to{stroke-dashoffset:0}}
.pct{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center}
.pv{font-size:220px;font-weight:500;letter-spacing:-.05em;line-height:1;font-variant-numeric:tabular-nums}.pv small{font-size:.4em;color:var(--rf-muted)}
.pl{font-size:40px;font-weight:600;color:var(--rf-muted);max-width:420px;margin-top:6px}
.lgs{display:flex;gap:40px;margin-top:70px;flex-wrap:wrap;justify-content:center}
.lg{display:flex;align-items:center;gap:16px;font-size:38px;font-weight:600;color:var(--rf-muted)}.lg i{width:28px;height:28px;border-radius:8px}

